CLASS zcl_html_viewer_sapevent DEFINITION PUBLIC FINAL CREATE PUBLIC.
  PUBLIC SECTION.
    METHODS get_html_with_sapevent_button
      RETURNING
        VALUE(rv_html_string) TYPE string.
ENDCLASS.

CLASS zcl_html_viewer_sapevent IMPLEMENTATION.
  METHOD get_html_with_sapevent_button.
    rv_html_string = |
      <!DOCTYPE html>
      <html>
      <head>
        <title>SAP Event Trigger</title>
        <style>
          body { font-family: Arial, sans-serif; margin: 20px; }
          button { padding: 10px 20px; font-size: 16px; cursor: pointer; }
        </style>
        <script>
          function triggerSapEvent() {
            try {
              // 'MY_CUSTOM_EVENT' ist der Event-Name, 'Hello from HTML!' ist der Parameter
              window.external.callSAPMethod('MY_CUSTOM_EVENT', 'Hello from HTML!');
              alert('SAP Event ausgelöst!');
            } catch (e) {
              alert('Fehler beim Auslösen des SAP Events: ' + e.message);
            }
          }
        </script>
      </head>
      <body>
        <h1>SAP Event aus HTML auslösen</h1>
        <p>Klicken Sie auf den Button, um ein SAP-Event zu triggern.</p>
        <button onclick="triggerSapEvent()">SAP Event auslösen</button>
      </body>
      </html>
    |.
  ENDMETHOD.
ENDCLASS.
